#include <iostream>
template <typename T>
class FSizeArr {
public:
    int length;
    T* data;
    // Write the constructor here!
};

runHarness:
int _pass = 0;
int _fail = 0;

void _test(int num, int got, int expected) {
    bool passed = got == expected;
    std::cout << "---------------------\n";
    std::cout << "Test " << num << ":\n";
    std::cout << (passed ? "Pass" : "Fail") << "\n";
    if (passed) _pass++; else _fail++;
}

int main() {
    FSizeArr<int> tester(2);
    tester.data[0] = 21;
    tester.data[1] = -1;
    _test(1, 12, FSizeArr<int>(12).length);
    _test(2, 1, FSizeArr<char>(-10).length);
    _test(3, 21, tester.data[0]);
    _test(2, -1, tester.data[1]);
    std::cout << "---------------------\n";
    std::cout << _pass << " passed, " << _fail << " failed\n";
    return 0;
}
